import { mkdtempSync, readdirSync, readFileSync, rmSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { createHostRuntime } from '/Users/bytedance/Documents/MRepo/bear-harness/packages/host-runtime/dist/index.js';
import { productConfig } from '/Users/bytedance/Documents/MRepo/bear-harness/packages/product-config/dist/index.js';
const fixture='/Users/bytedance/Documents/MRepo/bear-harness/packages/host-runtime/tests/fixtures/characters';
const vault={securityLevel:'session',isEncryptionAvailable:()=>false,encryptString:v=>Buffer.from(v),decryptString:v=>v.toString('utf8')};
function files(root,dir=root) {return readdirSync(dir,{withFileTypes:true}).flatMap(e=>{const p=join(dir,e.name);if(e.isDirectory())return files(root,p);const b=e.name==='character.yaml'?Buffer.from(readFileSync(p,'utf8').replace('id: jizhou','id: audit-other')):readFileSync(p);return [{path:`package/${relative(root,p)}`,base64:b.toString('base64')}];});}
async function run(mode) {
 const dir=mkdtempSync(join(tmpdir(),'bear-audit-lifecycle-'));
 const host=createHostRuntime({dataDir:dir,characterSeedRoot:fixture,productConfig,credentialVault:vault});
 let pinned;
 const release=Promise.withResolvers();
 try {
  const imported=await host.dispatch('character.import',{files:files(join(fixture,'jizhou'))});
  if(!imported.ok)throw new Error(JSON.stringify(imported));
  const started=Promise.withResolvers();
  pinned=host.lifecycle.route(async r=>{started.resolve(r);await release.promise;});
  const old=await started.promise;
  const switched=await host.dispatch('character.activate',{characterId:'audit-other'});
  if(!switched.ok)throw new Error(JSON.stringify(switched));
  if(mode==='reactivation') {
   const back=await host.dispatch('character.activate',{characterId:'jizhou'});
   if(!back.ok)throw new Error(JSON.stringify(back));
   const current=host.lifecycle.active();
   const sharedDatabase=old.runtime.db===current.runtime.db;
   release.resolve(); await pinned;
   let queryError;
   try {current.runtime.db.connection.prepare('SELECT 1').get();} catch(e){queryError=e.message;}
   console.log(JSON.stringify({mode,oldRuntime:old.runtimeId,newRuntime:current.runtimeId,sharedDatabase,queryError}));
  } else {
   const before=host.lifecycle.snapshot();
   const deletion=await host.dispatch('character.runtimeDelete',{characterId:'jizhou'});
   console.log(JSON.stringify({mode,pendingBefore:before.runtimes[old.runtimeId],deletion,oldStillRegistered:!!host.lifecycle.snapshot().runtimes[old.runtimeId],directoryExists:existsSync(join(dir,'companions','jizhou'))}));
   release.resolve();await pinned;
  }
 } finally {release.resolve();await pinned?.catch(()=>{});await host.close().catch(()=>{});rmSync(dir,{recursive:true,force:true});}
}
await run('reactivation');
await run('delete-retiring');

