import type { CompanionClient } from "@bear-harness/companion-client";
import type {
	ConversationActiveResponse,
	ConversationDetail,
	ConversationSummary,
	LivePush,
	PiSessionEntry,
	RpcEnvelope,
	RunListResponse,
	SnapshotResponse,
} from "@bear-harness/protocol";
import { LivePush as LivePushSchema } from "@bear-harness/protocol/schema";
import { isCancelledError, QueryClient, QueryClientProvider } from "@tanstack/solid-query";
import { waitFor } from "@testing-library/dom";
import { createComponent, createRoot } from "solid-js";
import { describe, expect, it, vi } from "/Users/bytedance/Documents/MRepo/bear-harness/packages/companion-ui/node_modules/vitest/dist/index.js";
import { type CompanionStore, createCompanionStore } from "/Users/bytedance/Documents/MRepo/bear-harness/packages/companion-ui/src/stores/companion.tsx";
import { createTestClient, pushPiEvent, THEMED_CHARACTER } from "/Users/bytedance/Documents/MRepo/bear-harness/packages/companion-ui/tests/fixtures.ts";

const summary = (conversationId: string): ConversationSummary => ({
	conversationId,
	name: `Conversation ${conversationId}`,
	created: "2026-01-01T00:00:00.000Z",
	modified: "2026-01-01T00:00:00.000Z",
	messageCount: 0,
	firstMessage: "",
	isStreaming: false,
});

const detail = (conversationId: string, entries: PiSessionEntry[] = []): ConversationDetail => ({
	conversationId,
	name: `Conversation ${conversationId}`,
	branch: {
		entries,
		hasMoreBefore: false,
		activeLeafId: entries.at(-1)?.id,
		latestLeafIds: entries.length ? [entries[entries.length - 1]!.id] : [],
	},
	live: {
		isStreaming: false,
		isRetrying: false,
		retryAttempt: 0,
		isCompacting: false,
		pendingToolCallIds: [],
		steering: [],
		followUp: [],
	},
});

const userEntry = (id: string, text: string) =>
	({
		type: "message",
		id,
		parentId: null,
		timestamp: "2026-01-01T00:00:00.000Z",
		message: { role: "user", content: text, timestamp: 1 },
	}) satisfies PiSessionEntry;

const assistantEntry = (id: string, text: string) =>
	({
		type: "message",
		id,
		parentId: null,
		timestamp: "2026-01-01T00:00:00.000Z",
		message: {
			role: "assistant",
			content: [{ type: "text", text }],
			api: "openai-responses",
			provider: "relay",
			model: "model",
			usage: {
				input: 1,
				output: 1,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 2,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			stopReason: "stop",
			timestamp: 2,
			responseId: "response-1",
		},
	}) satisfies PiSessionEntry;

const streamingAssistant = (text: string) => ({
	role: "assistant" as const,
	content: [{ type: "text" as const, text }],
	api: "openai-responses" as const,
	provider: "relay",
	model: "model",
	usage: {
		input: 1,
		output: 1,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 2,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	},
	stopReason: "stop" as const,
	timestamp: 2,
	responseId: "stream-response",
});

function mockActiveConversation(
	client: CompanionClient,
	initial: ConversationDetail | null = detail("a"),
) {
	let activeConversation = initial;
	const select = (next: ConversationDetail | null) => {
		activeConversation = next;
		return { ok: true as const, data: { activeConversation } };
	};
	client.conversation.activeGet = vi.fn(() => Promise.resolve(select(activeConversation)));
	client.conversation.select = vi.fn(({ conversationId }) =>
		Promise.resolve(select(detail(conversationId))),
	);
	client.conversation.open = vi.fn(({ conversationId }) =>
		Promise.resolve({ ok: true as const, data: detail(conversationId) }),
	);
	return select;
}

function createStoreWithCleanup(client: CompanionClient) {
	let dispose = () => undefined;
	let store: CompanionStore | undefined;
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false, staleTime: 30_000 } },
	});
	createRoot((cleanup) => {
		dispose = cleanup;
		createComponent(QueryClientProvider, {
			client: queryClient,
			get children() {
				store = createCompanionStore(client);
				return undefined;
			},
		});
	});
	if (!store) throw new Error("store was not created inside QueryClientProvider");
	return { store, queryClient, dispose };
}


it("settled background projection survives unrelated navigation", async () => {
 const { client } = createTestClient();
 mockActiveConversation(client, detail("a"));
 client.conversation.list = vi.fn(async () => ({ ok: true as const, data: { conversations: [summary("a"), summary("b"), summary("c")] } }));
 const pending = Promise.withResolvers<RpcEnvelope<ConversationDetail>>();
 client.conversation.open = vi.fn(() => pending.promise);
 const { store, dispose } = createStoreWithCleanup(client);
 try {
  await waitFor(() => expect(store.liveConnectionStatus).toBe("connected"));
  pushPiEvent(client, { type: "pi", conversationId: "b", version: { instanceId: "native-b", sequence: 1 }, event: { type: "agent_start" } });
  await waitFor(() => expect(store.conversations.find(x => x.conversationId === "b")?.isStreaming).toBe(true));
  pushPiEvent(client, { type: "pi", conversationId: "b", version: { instanceId: "native-b", sequence: 2 }, event: { type: "agent_settled" } });
  await waitFor(() => expect(client.conversation.open).toHaveBeenCalledTimes(1));
  await store.selectConversation("c");
  const settled = detail("b");
  settled.live.version = { instanceId: "native-b", sequence: 2 };
  pending.resolve({ ok: true, data: settled });
  await new Promise(resolve => setTimeout(resolve, 50));
  expect(store.activeConversationId).toBe("c");
  expect(client.conversation.open).toHaveBeenCalledTimes(1);
  expect(store.conversations.find(x => x.conversationId === "b")?.isStreaming).toBe(false);
  expect(store.completedConversationIds.has("b")).toBe(true);
 } finally { dispose(); }
});

it("does not claim reconnected after the authoritative snapshot fails", async () => {
 const { client } = createTestClient();
 mockActiveConversation(client, detail("a", [userEntry("stale", "before reconnect")]));
 const disconnect = Promise.withResolvers<void>();
 const subscribe = client.live.subscribe;
 let subscriptions = 0;
 client.live.subscribe = vi.fn(async signal => ++subscriptions === 1 ? {
  async *[Symbol.asyncIterator]() {
   yield { type: "pi" as const, conversationId: "a", event: { type: "agent_start" as const } };
   await disconnect.promise;
   throw new Error("disconnect");
  }
 } : subscribe(signal));
 const { store, dispose } = createStoreWithCleanup(client);
 try {
  await waitFor(() => expect(store.liveConnectionStatus).toBe("connected"));
  await waitFor(() => expect(store.activePiLiveState?.isStreaming).toBe(true));
  client.conversation.activeGet = vi.fn()
   .mockRejectedValueOnce(new Error("temporary snapshot failure"))
   .mockResolvedValue({ ok: true, data: { activeConversation: detail("a", [userEntry("fresh", "authoritative completion")]) } });
  disconnect.resolve();
  await waitFor(() => expect(client.live.subscribe).toHaveBeenCalledTimes(2));
  await new Promise(resolve => setTimeout(resolve, 150));
  expect(store.liveConnectionStatus).toBe("connected");
  expect(client.conversation.activeGet).toHaveBeenCalledTimes(1);
  expect(store.activePiLiveState?.isStreaming).toBe(false);
  expect(store.activePiEntries?.at(-1)?.id).toBe("fresh");
 } finally { dispose(); }
});
